/// <summary>
/// Extension of validate method
/// </summary>
/// <returns>boolean</returns>
public boolean validate()
{  
    boolean ret = next validate();

    ProjPlanVersion locProjPlanVersion = ProjPlanVersion::findByActivityNumber(element.ProjJournalTrans.ActivityNumber);

    if(locProjPlanVersion.EndNode == FalseTrue::False)
    {
        ret = checkFailed("@NDX:NXAActivityCheckFailed");
    }

    return ret;
}
